package com.proximity;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridLayout;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JSlider;
import javax.swing.event.ChangeListener;

/** A compact R/G/B/A slider dialog, since the platform color chooser has no reliable alpha control. */
final class RgbaColorChooser
{
    private RgbaColorChooser()
    {
    }

    static Color pickColor(Component parent, String title, Color initial)
    {
        JSlider redSlider = channelSlider(initial.getRed());
        JSlider greenSlider = channelSlider(initial.getGreen());
        JSlider blueSlider = channelSlider(initial.getBlue());
        JSlider alphaSlider = channelSlider(initial.getAlpha());

        JPanel preview = new JPanel();
        preview.setPreferredSize(new Dimension(40, 40));
        preview.setBorder(BorderFactory.createLineBorder(Color.GRAY));

        ChangeListener update = e -> preview.setBackground(new Color(
            redSlider.getValue(), greenSlider.getValue(), blueSlider.getValue(), alphaSlider.getValue()));
        redSlider.addChangeListener(update);
        greenSlider.addChangeListener(update);
        blueSlider.addChangeListener(update);
        alphaSlider.addChangeListener(update);
        update.stateChanged(null);

        JPanel sliders = new JPanel(new GridLayout(4, 1, 0, 4));
        sliders.add(channelRow("R", redSlider));
        sliders.add(channelRow("G", greenSlider));
        sliders.add(channelRow("B", blueSlider));
        sliders.add(channelRow("A", alphaSlider));

        JPanel content = new JPanel(new BorderLayout(10, 0));
        content.add(sliders, BorderLayout.CENTER);
        content.add(preview, BorderLayout.EAST);

        int result = JOptionPane.showConfirmDialog(
            parent, content, title, JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);
        if (result != JOptionPane.OK_OPTION)
        {
            return null;
        }
        return new Color(
            redSlider.getValue(), greenSlider.getValue(), blueSlider.getValue(), alphaSlider.getValue());
    }

    private static JSlider channelSlider(int value)
    {
        return new JSlider(0, 255, value);
    }

    private static JPanel channelRow(String label, JSlider slider)
    {
        JPanel row = new JPanel(new BorderLayout(6, 0));
        JLabel labelComponent = new JLabel(label);
        labelComponent.setPreferredSize(new Dimension(12, 16));
        row.add(labelComponent, BorderLayout.WEST);
        row.add(slider, BorderLayout.CENTER);
        return row;
    }
}

package com.proximity;

import java.awt.Color;

/**
 * A fixed "+24 per channel" hover lighten doesn't read for every color (it clips
 * to invisible near white, and barely registers on already-bright/saturated hues).
 * Instead blend toward black or white, whichever contrasts more with the base color,
 * so the hover state is always clearly visible regardless of hue or lightness.
 */
final class HoverColors
{
    private static final double BLEND = 0.35;

    private HoverColors()
    {
    }

    static Color highlight(Color base)
    {
        double luminance = 0.299 * base.getRed() + 0.587 * base.getGreen() + 0.114 * base.getBlue();
        Color target = luminance > 140 ? Color.BLACK : Color.WHITE;

        int r = blend(base.getRed(), target.getRed());
        int g = blend(base.getGreen(), target.getGreen());
        int b = blend(base.getBlue(), target.getBlue());
        return new Color(r, g, b, base.getAlpha());
    }

    private static int blend(int channel, int target)
    {
        return (int) Math.round(channel * (1 - BLEND) + target * BLEND);
    }
}

package com.proximity;

import java.awt.Color;

class MonsterRule
{
    String name;
    int dangerThreshold;
    int warningThreshold;

    int dangerFillRgb;
    int dangerBorderRgb;
    int warningFillRgb;
    int warningBorderRgb;
    int safeFillRgb;
    int safeBorderRgb;

    MonsterRule(String name)
    {
        this.name = name;
        this.dangerThreshold = 0;
        this.warningThreshold = 4;

        this.dangerFillRgb = new Color(255, 0, 0, 90).getRGB();
        this.dangerBorderRgb = Color.RED.darker().getRGB();
        this.warningFillRgb = new Color(255, 255, 0, 90).getRGB();
        this.warningBorderRgb = Color.YELLOW.darker().getRGB();
        this.safeFillRgb = new Color(0, 255, 0, 90).getRGB();
        this.safeBorderRgb = Color.GREEN.darker().getRGB();
    }

    Color dangerFill()
    {
        return new Color(dangerFillRgb, true);
    }

    Color dangerBorder()
    {
        return new Color(dangerBorderRgb, true);
    }

    Color warningFill()
    {
        return new Color(warningFillRgb, true);
    }

    Color warningBorder()
    {
        return new Color(warningBorderRgb, true);
    }

    Color safeFill()
    {
        return new Color(safeFillRgb, true);
    }

    Color safeBorder()
    {
        return new Color(safeBorderRgb, true);
    }

    Color fillFor(int distance)
    {
        if (distance <= dangerThreshold)
        {
            return dangerFill();
        }
        if (distance <= warningThreshold)
        {
            return warningFill();
        }
        return safeFill();
    }

    Color borderFor(int distance)
    {
        if (distance <= dangerThreshold)
        {
            return dangerBorder();
        }
        if (distance <= warningThreshold)
        {
            return warningBorder();
        }
        return safeBorder();
    }
}

package com.proximity;

import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JPanel;

class RoundedPanel extends JPanel
{
    private final int arc;

    RoundedPanel(int arc)
    {
        this.arc = arc;
        setOpaque(false);
    }

    @Override
    protected void paintComponent(Graphics g)
    {
        Graphics2D g2 = (Graphics2D) g.create();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g2.setColor(getBackground());
        g2.fillRoundRect(0, 0, getWidth(), getHeight(), arc, arc);
        g2.dispose();
        super.paintComponent(g);
    }
}

package com.proximity;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
    name = "Proximity Tags",
    description = "Marks the true tiles of named monsters with a color based on distance to you",
    tags = {"proximity", "npc", "distance", "overlay", "pvm", "pking", "tag"}
)
public class ProximityTagsPlugin extends Plugin
{
    private static final String CONFIG_GROUP = "proximityTags";
    private static final String RULES_KEY = "rules";

    private final List<MonsterRule> rules = new ArrayList<>();

    @Inject
    private Gson gson;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private ProximityTagsOverlay overlay;

    @Inject
    private ConfigManager configManager;

    @Inject
    private ClientToolbar clientToolbar;

    private ProximityTagsPanel panel;
    private NavigationButton navButton;

    @Override
    protected void startUp()
    {
        loadRules();
        overlayManager.add(overlay);

        panel = new ProximityTagsPanel(this);
        navButton = NavigationButton.builder()
            .tooltip("Proximity Tags")
            .icon(buildIcon())
            .priority(5)
            .panel(panel)
            .build();
        clientToolbar.addNavigation(navButton);
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
        clientToolbar.removeNavigation(navButton);
        panel = null;
        navButton = null;
    }

    List<MonsterRule> getRules()
    {
        return rules;
    }

    MonsterRule findRule(String npcName)
    {
        for (MonsterRule rule : rules)
        {
            if (rule.name.equalsIgnoreCase(npcName))
            {
                return rule;
            }
        }
        return null;
    }

    void addRule(String name)
    {
        if (findRule(name) != null)
        {
            return;
        }
        rules.add(new MonsterRule(name));
        saveRules();
    }

    void removeRule(MonsterRule rule)
    {
        rules.remove(rule);
        saveRules();
    }

    void saveRules()
    {
        configManager.setConfiguration(CONFIG_GROUP, RULES_KEY, gson.toJson(rules));
    }

    private static final char[][] ICON_GRID = {
        {'P', 'R', 'O', 'X'},
        {'T', 'A', 'G', 'S'}
    };

    private BufferedImage buildIcon()
    {
        int size = 32;
        int cellWidth = size / ICON_GRID[0].length;
        int cellHeight = size / ICON_GRID.length;

        BufferedImage icon = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = icon.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
        g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);

        g.setColor(Color.BLACK);
        g.fillRect(0, 0, size, size);

        g.setColor(Color.YELLOW);
        g.setFont(new Font(Font.MONOSPACED, Font.BOLD, cellHeight - 2));
        FontMetrics metrics = g.getFontMetrics();

        for (int row = 0; row < ICON_GRID.length; row++)
        {
            for (int col = 0; col < ICON_GRID[row].length; col++)
            {
                String letter = String.valueOf(ICON_GRID[row][col]);
                int cellX = col * cellWidth;
                int cellY = row * cellHeight;
                int textX = cellX + (cellWidth - metrics.stringWidth(letter)) / 2;
                int textY = cellY + (cellHeight - metrics.getHeight()) / 2 + metrics.getAscent();
                g.drawString(letter, textX, textY);
            }
        }

        g.dispose();
        return icon;
    }

    private void loadRules()
    {
        rules.clear();
        String json = configManager.getConfiguration(CONFIG_GROUP, RULES_KEY);
        if (json == null || json.isEmpty())
        {
            return;
        }
        List<MonsterRule> loaded = gson.fromJson(json, new TypeToken<List<MonsterRule>>()
        {
        }.getType());
        if (loaded != null)
        {
            rules.addAll(loaded);
        }
    }
}

package com.proximity;

import java.awt.Color;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.JButton;

class RoundedButton extends JButton
{
    private final int arc;
    private final boolean ghost;
    private boolean hovered;

    RoundedButton(String text, int arc)
    {
        this(text, arc, false);
    }

    /** Ghost buttons are invisible until hovered, then show a filled rounded background. */
    RoundedButton(String text, int arc, boolean ghost)
    {
        super(text);
        this.arc = arc;
        this.ghost = ghost;
        setContentAreaFilled(false);
        setFocusPainted(false);
        setBorderPainted(false);
        setOpaque(false);
        setMargin(new java.awt.Insets(0, 0, 0, 0));
        addMouseListener(new MouseAdapter()
        {
            @Override
            public void mouseEntered(MouseEvent e)
            {
                hovered = true;
                repaint();
            }

            @Override
            public void mouseExited(MouseEvent e)
            {
                hovered = false;
                repaint();
            }
        });
    }

    @Override
    protected void paintComponent(Graphics g)
    {
        Graphics2D g2 = (Graphics2D) g.create();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        if (ghost)
        {
            if (hovered)
            {
                g2.setColor(getBackground());
                g2.fillRoundRect(0, 0, getWidth() - 1, getHeight() - 1, arc, arc);
            }
        }
        else
        {
            Color base = getBackground();
            g2.setColor(hovered ? HoverColors.highlight(base) : base);
            g2.fillRoundRect(0, 0, getWidth() - 1, getHeight() - 1, arc, arc);
            g2.setColor(darken(base));
            g2.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, arc, arc);
        }

        g2.dispose();
        super.paintComponent(g);
    }

    private static Color darken(Color c)
    {
        return new Color(
            Math.max(0, c.getRed() - 30),
            Math.max(0, c.getGreen() - 30),
            Math.max(0, c.getBlue() - 30));
    }
}

package com.proximity;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.geom.Area;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class ProximityTagsOverlay extends Overlay
{
    private final Client client;
    private final ProximityTagsPlugin plugin;

    @Inject
    ProximityTagsOverlay(Client client, ProximityTagsPlugin plugin)
    {
        this.client = client;
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        Player local = client.getLocalPlayer();
        if (local == null)
        {
            return null;
        }

        for (NPC npc : client.getTopLevelWorldView().npcs())
        {
            if (npc.isDead() || npc.getName() == null)
            {
                continue;
            }

            MonsterRule rule = plugin.findRule(npc.getName());
            if (rule == null)
            {
                continue;
            }

            int distance = npc.getWorldArea().distanceTo(local.getWorldArea());
            Color fillColor = rule.fillFor(distance);
            Color borderColor = rule.borderFor(distance);
            drawTrueTiles(graphics, npc.getWorldArea(), fillColor, borderColor);
        }

        return null;
    }

    private void drawTrueTiles(Graphics2D graphics, WorldArea area, Color fillColor, Color borderColor)
    {
        Area regionShape = new Area();

        for (int dx = 0; dx < area.getWidth(); dx++)
        {
            for (int dy = 0; dy < area.getHeight(); dy++)
            {
                WorldPoint tile = new WorldPoint(area.getX() + dx, area.getY() + dy, area.getPlane());
                LocalPoint local = LocalPoint.fromWorld(client, tile);
                if (local == null)
                {
                    continue;
                }

                Polygon poly = Perspective.getCanvasTilePoly(client, local);
                if (poly == null)
                {
                    continue;
                }

                regionShape.add(new Area(poly));
            }
        }

        if (regionShape.isEmpty())
        {
            return;
        }

        graphics.setColor(fillColor);
        graphics.fill(regionShape);
        graphics.setColor(borderColor);
        graphics.draw(regionShape);
    }
}

package com.proximity;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.Rectangle;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextField;
import javax.swing.Scrollable;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

class ProximityTagsPanel extends PluginPanel
{
    private static final int SLIDER_MAX_TILES = 20;
    private static final int CARD_ARC = 14;
    private static final int BUTTON_ARC = 8;
    private static final Color CARD_BACKGROUND = ColorScheme.DARKER_GRAY_COLOR;
    private static final Color SECTION_BACKGROUND = ColorScheme.DARK_GRAY_COLOR;

    private final ProximityTagsPlugin plugin;
    private final JPanel rulesContainer = new ScrollableViewport();
    private final JTextField nameField = new JTextField();

    /** Forces the rules list to always match the viewport width, so the vertical scrollbar never pushes content into a horizontal scrollbar. */
    private static class ScrollableViewport extends JPanel implements Scrollable
    {
        @Override
        public Dimension getPreferredScrollableViewportSize()
        {
            return getPreferredSize();
        }

        @Override
        public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
        {
            return 16;
        }

        @Override
        public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
        {
            return 64;
        }

        @Override
        public boolean getScrollableTracksViewportWidth()
        {
            return true;
        }

        @Override
        public boolean getScrollableTracksViewportHeight()
        {
            return false;
        }
    }

    ProximityTagsPanel(ProximityTagsPlugin plugin)
    {
        super(false);
        this.plugin = plugin;

        setLayout(new BorderLayout(0, 10));
        setBorder(BorderFactory.createEmptyBorder(12, 10, 10, 10));

        add(buildAddPanel(), BorderLayout.NORTH);

        rulesContainer.setLayout(new BoxLayout(rulesContainer, BoxLayout.Y_AXIS));
        rulesContainer.setOpaque(false);
        rulesContainer.setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 0));

        JScrollPane scrollPane = new JScrollPane(rulesContainer);
        scrollPane.setBorder(BorderFactory.createEmptyBorder());
        scrollPane.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        scrollPane.getViewport().setOpaque(false);
        scrollPane.setOpaque(false);
        scrollPane.getVerticalScrollBar().setUnitIncrement(16);

        add(scrollPane, BorderLayout.CENTER);

        rebuild();
    }

    private JPanel buildAddPanel()
    {
        RoundedPanel addPanel = new RoundedPanel(CARD_ARC);
        addPanel.setLayout(new BorderLayout(8, 6));
        addPanel.setBackground(SECTION_BACKGROUND);
        addPanel.setBorder(BorderFactory.createEmptyBorder(10, 12, 10, 12));

        JLabel title = new JLabel("Add monster");
        title.setForeground(Color.WHITE);
        title.setFont(title.getFont().deriveFont(java.awt.Font.BOLD, 12f));

        JPanel inputRow = new JPanel(new BorderLayout(8, 0));
        inputRow.setOpaque(false);
        nameField.setToolTipText("Exact monster name, e.g. Ba-Ba");
        nameField.putClientProperty("JTextField.placeholderText", "e.g. Ba-Ba");
        nameField.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
            BorderFactory.createEmptyBorder(4, 6, 4, 6)));
        nameField.addActionListener(e -> addFromField());

        RoundedButton addButton = new RoundedButton("+ Add", BUTTON_ARC);
        addButton.setForeground(Color.WHITE);
        addButton.setBackground(ColorScheme.BRAND_ORANGE);
        addButton.setToolTipText("Add this monster to the tag list");
        addButton.setPreferredSize(new Dimension(64, 28));
        addButton.addActionListener(e -> addFromField());

        inputRow.add(nameField, BorderLayout.CENTER);
        inputRow.add(addButton, BorderLayout.EAST);

        addPanel.add(title, BorderLayout.NORTH);
        addPanel.add(inputRow, BorderLayout.CENTER);
        return addPanel;
    }

    private void addFromField()
    {
        String name = nameField.getText().trim();
        if (name.isEmpty())
        {
            return;
        }
        plugin.addRule(name);
        nameField.setText("");
        rebuild();
    }

    void rebuild()
    {
        rulesContainer.removeAll();
        for (MonsterRule rule : plugin.getRules())
        {
            JPanel row = buildRow(rule);
            row.setAlignmentX(JPanel.LEFT_ALIGNMENT);
            rulesContainer.add(row);
            rulesContainer.add(Box.createVerticalStrut(5));
        }
        rulesContainer.add(Box.createVerticalGlue());
        rulesContainer.revalidate();
        rulesContainer.repaint();
    }

    private JPanel buildRow(MonsterRule rule)
    {
        RoundedPanel row = new RoundedPanel(CARD_ARC);
        row.setLayout(new BoxLayout(row, BoxLayout.Y_AXIS));
        row.setBorder(BorderFactory.createEmptyBorder(7, 12, 7, 12));
        row.setBackground(CARD_BACKGROUND);
        row.setAlignmentX(JPanel.LEFT_ALIGNMENT);

        JPanel header = new JPanel(new BorderLayout());
        header.setOpaque(false);
        JLabel nameLabel = new JLabel(rule.name);
        nameLabel.setForeground(Color.WHITE);
        nameLabel.setFont(nameLabel.getFont().deriveFont(java.awt.Font.BOLD, 13f));

        RoundedButton removeButton = new RoundedButton("×", BUTTON_ARC, true);
        removeButton.setForeground(Color.WHITE);
        removeButton.setFont(removeButton.getFont().deriveFont(java.awt.Font.BOLD, 14f));
        removeButton.setBackground(ColorScheme.PROGRESS_ERROR_COLOR);
        removeButton.setToolTipText("Remove " + rule.name);
        removeButton.setPreferredSize(new Dimension(22, 22));
        removeButton.addActionListener(e ->
        {
            plugin.removeRule(rule);
            rebuild();
        });
        header.add(nameLabel, BorderLayout.WEST);
        header.add(removeButton, BorderLayout.EAST);

        RangeSlider slider = new RangeSlider(rule, SLIDER_MAX_TILES, plugin::saveRules);
        slider.setAlignmentX(JPanel.CENTER_ALIGNMENT);
        slider.setMaximumSize(new Dimension(Integer.MAX_VALUE, slider.getPreferredSize().height));

        JPanel colorRow = new JPanel(new GridLayout(1, 3, 10, 0));
        colorRow.setOpaque(false);
        colorRow.setAlignmentX(JPanel.CENTER_ALIGNMENT);
        colorRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, colorRow.getPreferredSize().height));
        colorRow.add(colorPickerPair("Danger", rule.dangerFill(), rule.dangerBorder(),
            fill ->
            {
                rule.dangerFillRgb = fill.getRGB();
                plugin.saveRules();
                slider.repaint();
            },
            border ->
            {
                rule.dangerBorderRgb = border.getRGB();
                plugin.saveRules();
                slider.repaint();
            }));
        colorRow.add(colorPickerPair("Warn", rule.warningFill(), rule.warningBorder(),
            fill ->
            {
                rule.warningFillRgb = fill.getRGB();
                plugin.saveRules();
                slider.repaint();
            },
            border ->
            {
                rule.warningBorderRgb = border.getRGB();
                plugin.saveRules();
                slider.repaint();
            }));
        colorRow.add(colorPickerPair("Safe", rule.safeFill(), rule.safeBorder(),
            fill ->
            {
                rule.safeFillRgb = fill.getRGB();
                plugin.saveRules();
                slider.repaint();
            },
            border ->
            {
                rule.safeBorderRgb = border.getRGB();
                plugin.saveRules();
                slider.repaint();
            }));

        row.add(header);
        row.add(Box.createVerticalStrut(3));
        row.add(slider);
        row.add(Box.createVerticalStrut(3));
        row.add(colorRow);

        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
        return row;
    }

    private JPanel colorPickerPair(
        String category,
        Color fill,
        Color border,
        java.util.function.Consumer<Color> onFillChange,
        java.util.function.Consumer<Color> onBorderChange)
    {
        JPanel wrapper = new JPanel();
        wrapper.setLayout(new BoxLayout(wrapper, BoxLayout.Y_AXIS));
        wrapper.setOpaque(false);

        JLabel categoryLabel = new JLabel(category, SwingConstants.CENTER);
        categoryLabel.setForeground(Color.LIGHT_GRAY);
        categoryLabel.setFont(categoryLabel.getFont().deriveFont(java.awt.Font.BOLD, 10f));
        categoryLabel.setAlignmentX(JLabel.CENTER_ALIGNMENT);

        DualColorSwatch swatch = new DualColorSwatch(fill, border, onFillChange, onBorderChange);
        swatch.setAlignmentX(JPanel.CENTER_ALIGNMENT);

        wrapper.add(categoryLabel);
        wrapper.add(Box.createVerticalStrut(1));
        wrapper.add(swatch);
        return wrapper;
    }
}

package com.proximity;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.JComponent;

/**
 * A two-thumb slider that splits 0..max into danger/warning/safe zones,
 * colored to match a MonsterRule, with draggable thumbs for the two thresholds.
 *
 * <p>The thumbs can never cross (danger always &lt;= warning), but they can land on
 * the exact same tile count, stacking on top of each other. When that happens, simple
 * "pick whichever thumb is nearer the click" breaks down — both thumbs are at the same
 * pixel, so the same one wins the tie every time and the other becomes unreachable by
 * mouse. Instead, once stacked, the next drag's direction decides which thumb moves:
 * dragging right grows the warning side, dragging left grows the danger side, since
 * those are the only directions that can produce a visible change from a dead stop.
 */
class RangeSlider extends JComponent
{
    private static final int THUMB_RADIUS = 5;
    private static final int TRACK_HEIGHT = 8;
    private static final int LABEL_HEIGHT = 12;
    private static final int LABEL_BASELINE = LABEL_HEIGHT - 3;
    private static final int STACKED_THUMB_OFFSET = 3;

    private final MonsterRule rule;
    private final int maxValue;
    private final Runnable onChange;
    private boolean draggingLow;
    private boolean draggingHigh;
    private boolean pendingStackDecision;
    private int pressX;

    RangeSlider(MonsterRule rule, int maxValue, Runnable onChange)
    {
        this.rule = rule;
        this.maxValue = maxValue;
        this.onChange = onChange;
        setPreferredSize(new Dimension(180, LABEL_HEIGHT + TRACK_HEIGHT + THUMB_RADIUS * 2));
        setMaximumSize(new Dimension(Integer.MAX_VALUE, getPreferredSize().height));
        updateTooltip();

        MouseAdapter mouse = new MouseAdapter()
        {
            @Override
            public void mousePressed(MouseEvent e)
            {
                pressX = e.getX();

                if (rule.dangerThreshold == rule.warningThreshold)
                {
                    // Thumbs are stacked: wait for a drag to reveal which one the user means.
                    pendingStackDecision = true;
                    draggingLow = false;
                    draggingHigh = false;
                    return;
                }

                pendingStackDecision = false;
                int lowX = pixelForValue(rule.dangerThreshold);
                int highX = pixelForValue(rule.warningThreshold);
                draggingLow = Math.abs(e.getX() - lowX) <= Math.abs(e.getX() - highX);
                draggingHigh = !draggingLow;
                handleDrag(e.getX());
            }

            @Override
            public void mouseDragged(MouseEvent e)
            {
                if (pendingStackDecision)
                {
                    if (e.getX() == pressX)
                    {
                        return;
                    }
                    draggingHigh = e.getX() > pressX;
                    draggingLow = !draggingHigh;
                    pendingStackDecision = false;
                }
                handleDrag(e.getX());
            }

            @Override
            public void mouseReleased(MouseEvent e)
            {
                draggingLow = false;
                draggingHigh = false;
                pendingStackDecision = false;
            }
        };
        addMouseListener(mouse);
        addMouseMotionListener(mouse);
    }

    private void handleDrag(int mouseX)
    {
        int value = valueForPixel(mouseX);
        if (draggingLow)
        {
            rule.dangerThreshold = Math.min(value, rule.warningThreshold);
        }
        else if (draggingHigh)
        {
            rule.warningThreshold = Math.max(value, rule.dangerThreshold);
        }
        updateTooltip();
        repaint();
        onChange.run();
    }

    private void updateTooltip()
    {
        if (rule.dangerThreshold == rule.warningThreshold)
        {
            setToolTipText("Danger and Warn are both " + rule.dangerThreshold
                + " tiles — drag left or right to separate them");
        }
        else
        {
            setToolTipText("Danger ≤ " + rule.dangerThreshold + " tiles, Warn ≤ " + rule.warningThreshold + " tiles");
        }
    }

    private int trackStartX()
    {
        return THUMB_RADIUS;
    }

    private int trackEndX()
    {
        return getWidth() - THUMB_RADIUS;
    }

    private int pixelForValue(int value)
    {
        double ratio = Math.max(0, Math.min(1, value / (double) maxValue));
        return trackStartX() + (int) Math.round(ratio * (trackEndX() - trackStartX()));
    }

    private int valueForPixel(int x)
    {
        double ratio = (x - trackStartX()) / (double) (trackEndX() - trackStartX());
        int value = (int) Math.round(ratio * maxValue);
        return Math.max(0, Math.min(maxValue, value));
    }

    @Override
    protected void paintComponent(Graphics g)
    {
        Graphics2D g2 = (Graphics2D) g.create();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        int trackY = LABEL_HEIGHT + (THUMB_RADIUS * 2 - TRACK_HEIGHT) / 2;
        int lowX = pixelForValue(rule.dangerThreshold);
        int highX = pixelForValue(rule.warningThreshold);
        boolean stacked = rule.dangerThreshold == rule.warningThreshold;

        paintZone(g2, rule.dangerFill(), rule.dangerBorder(), trackStartX(), trackY, lowX);
        paintZone(g2, rule.warningFill(), rule.warningBorder(), lowX, trackY, highX);
        paintZone(g2, rule.safeFill(), rule.safeBorder(), highX, trackY, trackEndX());

        g2.setFont(g2.getFont().deriveFont(10f));
        g2.setColor(Color.WHITE);
        if (stacked)
        {
            drawCenteredLabel(g2, String.valueOf(rule.dangerThreshold), lowX, LABEL_BASELINE);
        }
        else
        {
            drawCenteredLabel(g2, String.valueOf(rule.dangerThreshold), lowX, LABEL_BASELINE);
            drawCenteredLabel(g2, String.valueOf(rule.warningThreshold), highX, LABEL_BASELINE);
        }

        // Nudge stacked thumbs apart visually so it's clear there are two handles to grab, not one.
        int drawLowX = stacked ? lowX - STACKED_THUMB_OFFSET : lowX;
        int drawHighX = stacked ? highX + STACKED_THUMB_OFFSET : highX;
        drawThumb(g2, drawLowX, trackY + TRACK_HEIGHT / 2);
        drawThumb(g2, drawHighX, trackY + TRACK_HEIGHT / 2);

        g2.dispose();
    }

    private void paintZone(Graphics2D g2, Color fill, Color border, int fromX, int trackY, int toX)
    {
        int width = Math.max(1, toX - fromX);
        g2.setColor(fill);
        g2.fillRoundRect(fromX, trackY, width, TRACK_HEIGHT, 6, 6);
        g2.setColor(border);
        g2.drawRoundRect(fromX, trackY, width, TRACK_HEIGHT, 6, 6);
    }

    private void drawCenteredLabel(Graphics2D g2, String text, int centerX, int baselineY)
    {
        int width = g2.getFontMetrics().stringWidth(text);
        g2.drawString(text, centerX - width / 2, baselineY);
    }

    private void drawThumb(Graphics2D g2, int centerX, int centerY)
    {
        g2.setColor(Color.WHITE);
        g2.fillOval(centerX - THUMB_RADIUS, centerY - THUMB_RADIUS, THUMB_RADIUS * 2, THUMB_RADIUS * 2);
        g2.setColor(Color.DARK_GRAY);
        g2.drawOval(centerX - THUMB_RADIUS, centerY - THUMB_RADIUS, THUMB_RADIUS * 2, THUMB_RADIUS * 2);
    }
}

package com.proximity;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.Consumer;
import javax.swing.JComponent;

/**
 * A single 30x30 swatch acting as two buttons: the 14x14 center square edits the fill
 * color, the surrounding 8px ring edits the border color. No text labels.
 */
class DualColorSwatch extends JComponent
{
    private static final int SIZE = 30;
    private static final int INNER_SIZE = 14;
    private static final int INNER_OFFSET = (SIZE - INNER_SIZE) / 2;

    private final Consumer<Color> onFillChange;
    private final Consumer<Color> onBorderChange;
    private Color fillColor;
    private Color borderColor;
    private boolean hoverInner;
    private boolean hoverOuter;

    DualColorSwatch(Color initialFill, Color initialBorder, Consumer<Color> onFillChange, Consumer<Color> onBorderChange)
    {
        this.fillColor = initialFill;
        this.borderColor = initialBorder;
        this.onFillChange = onFillChange;
        this.onBorderChange = onBorderChange;

        setPreferredSize(new Dimension(SIZE, SIZE));
        setMaximumSize(new Dimension(SIZE, SIZE));
        setToolTipText("Center: fill color. Edge: border color.");

        MouseAdapter mouse = new MouseAdapter()
        {
            @Override
            public void mouseClicked(MouseEvent e)
            {
                if (isInner(e.getX(), e.getY()))
                {
                    Color chosen = RgbaColorChooser.pickColor(DualColorSwatch.this, "Fill color", fillColor);
                    if (chosen != null)
                    {
                        fillColor = chosen;
                        onFillChange.accept(chosen);
                        repaint();
                    }
                }
                else
                {
                    Color chosen = RgbaColorChooser.pickColor(DualColorSwatch.this, "Border color", borderColor);
                    if (chosen != null)
                    {
                        borderColor = chosen;
                        onBorderChange.accept(chosen);
                        repaint();
                    }
                }
            }

            @Override
            public void mouseMoved(MouseEvent e)
            {
                updateHover(isInner(e.getX(), e.getY()));
            }

            @Override
            public void mouseExited(MouseEvent e)
            {
                hoverInner = false;
                hoverOuter = false;
                repaint();
            }
        };
        addMouseListener(mouse);
        addMouseMotionListener(mouse);
    }

    private void updateHover(boolean inner)
    {
        boolean outer = !inner;
        if (inner != hoverInner || outer != hoverOuter)
        {
            hoverInner = inner;
            hoverOuter = outer;
            repaint();
        }
    }

    private boolean isInner(int x, int y)
    {
        return x >= INNER_OFFSET && x < INNER_OFFSET + INNER_SIZE
            && y >= INNER_OFFSET && y < INNER_OFFSET + INNER_SIZE;
    }

    @Override
    protected void paintComponent(Graphics g)
    {
        Graphics2D g2 = (Graphics2D) g.create();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        Color outer = hoverOuter ? HoverColors.highlight(borderColor) : borderColor;
        Color inner = hoverInner ? HoverColors.highlight(fillColor) : fillColor;

        g2.setColor(outer);
        g2.fillRoundRect(0, 0, SIZE - 1, SIZE - 1, 8, 8);

        g2.setColor(inner);
        g2.fillRect(INNER_OFFSET, INNER_OFFSET, INNER_SIZE, INNER_SIZE);

        g2.setColor(Color.BLACK);
        g2.drawRoundRect(0, 0, SIZE - 1, SIZE - 1, 8, 8);

        g2.dispose();
    }
}
